import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/ON.DXVlsWbj.js";import{_ as o}from"./chunks/M-S-NL4.PyU7auYU.js";import{_ as a,o as r,c as l,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"Follower iOS NightLite","description":"","frontmatter":{"source_hash":"12ee29c8aa","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/nightlite.md","filePath":"it/use/nightlite.md"}'),n={name:"it/use/nightlite.md"};function c(p,i,d,u,m,h){return r(),l("div",null,[...i[0]||(i[0]=[s('<p>NightLite è un servizio follower leggero e compatibile con Nightscout. È un&#39;alternativa più semplice alla gestione di un tuo sito Nightscout quando ti serve solo condividere la glicemia con i follower.</p><p>xDrip è il <strong>master</strong> (carica i tuoi dati). L&#39;<a href="https://apps.apple.com/us/app/nightlite/id6759909591" target="_blank" rel="noreferrer">app NightLite per iOS</a> (un fork di Nightguard, di Richard Lander) è il <strong>follower</strong> e mostra i tuoi dati su iPhone, iPad, Apple Watch o Mac.</p><div class="info custom-block"><p class="custom-block-title">Curiosità</p><p>xDrip invia solo le ultime 12 ore di letture glicemiche (con tendenza e delta) e i trattamenti, aggiornati a ogni nuova lettura (circa ogni 5 minuti).</p></div><h3 id="prerequisites" tabindex="-1">Prerequisiti <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisiti {#prerequisites}&quot;">​</a></h3><ul><li>xDrip su una <a href="./../install/download.html#pre-release">nightly</a> recente (minimo <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.03.01" target="_blank" rel="noreferrer">1 marzo 2026</a>).</li><li>Un URL NightLite per il tuo account. Contiene la tua chiave di sicurezza ed è l&#39;unica cosa che devi inserire: xDrip ne ricava il codice QR per i follower.</li><li>Per il follower: un iPhone o iPad (iOS 15+), Apple Watch (watchOS 9.1+) o Mac (macOS 12 con M1 o successivo) con l&#39;<a href="https://apps.apple.com/us/app/nightlite/id6759909591" target="_blank" rel="noreferrer">app NightLite</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>NightLite non può essere usato mentre xDrip funziona come <a href="./../install/nightscoutfollower.html">follower Nightscout</a>. Funziona solo quando xDrip è la tua sorgente dati principale.</p></div><h3 id="setup-the-master-xdrip" tabindex="-1">Configura il master (xDrip) <a class="header-anchor" href="#setup-the-master-xdrip" aria-label="Permalink to &quot;Configura il master (xDrip) {#setup-the-master-xdrip}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_cloud_upload_grey600_48dp.png" style="width:5%;"> Caricamento nel Cloud<br>   NightLite</p></div><p>Inserisci il tuo URL NightLite:</p><div class="admonition xdripitem"><p class="admonition-title">NightLite URL</p><p> Typically entered by scanning QR code from dashboard<br>  This contains your security key - do not disclose it</p></div><p>Poi attiva il caricamento:</p><div class="admonition xdripitem"><p class="admonition-title">Upload to NightLite<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Whether to upload to the remote service</p></div><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>L&#39;URL NightLite contiene la tua chiave di sicurezza. Chiunque lo possieda può accedere ai tuoi dati, quindi non condividerlo.</p></div><h3 id="connect-a-follower" tabindex="-1">Collega un follower <a class="header-anchor" href="#connect-a-follower" aria-label="Permalink to &quot;Collega un follower {#connect-a-follower}&quot;">​</a></h3><p>Una volta attivato il caricamento, xDrip può mostrare un codice QR che contiene tutta la tua configurazione. È questo che il follower scansiona: non c&#39;è nulla da digitare sul dispositivo follower.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Codice QR</p><p> Codice a barre da scansionare per configurare i follower</p></div><ol><li>Installa l&#39;<a href="https://apps.apple.com/us/app/nightlite/id6759909591" target="_blank" rel="noreferrer">app NightLite</a> sul dispositivo follower.</li><li>Sul telefono master, tocca <strong>Mostra Codice QR</strong>. xDrip mostra il codice QR <code>NightLite configuration</code>.</li><li>Nelle preferenze dell&#39;app NightLite, tocca l&#39;icona di scansione accanto al campo dell&#39;URL Nightscout e scansiona il codice QR dallo schermo del master.</li></ol><img src="'+o+'" style="zoom:33%;"><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Il servizio NightLite può inviare notifiche a xDrip e, se necessario, interrompere il caricamento da remoto.</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',21)])])}const x=a(n,[["render",c]]);export{b as __pageData,x as default};
